from utils.logger import log_event

def verify_credentials(user, password, db):
    # Validate malformed inputs
    if user is None or password is None or db is None:
        log_event("login_malformed", user)
        raise ValueError("Malformed login input")

    if not isinstance(db, dict):
        log_event("login_malformed", user)
        raise ValueError("Malformed database input")

    if user not in db:
        log_event("login_failed", user)
        return False

    record = db.get(user)
    if not isinstance(record, dict) or "password" not in record:
        log_event("login_malformed", user)
        raise ValueError("Malformed user record")

    if record["password"] != password:
        log_event("login_failed", user)
        return False

    return True

